#include <stddef.h>
#include <stdint.h>

uint64_t quickproof_rnd(void);

static uint64_t qp_cbmc_shape(uint64_t max)
{
	switch (quickproof_rnd() % 4) {
	case 0:
		return quickproof_rnd() % 17;
	case 1:
		return max - quickproof_rnd() % 17;
	case 2:
		return quickproof_rnd() % 4096;
	default:
		return quickproof_rnd() & max;
	}
}

uint8_t nondet_u8(void)
{
	return (uint8_t) qp_cbmc_shape(255);
}

uint32_t nondet_u32(void)
{
	return (uint32_t) qp_cbmc_shape(4294967295U);
}

size_t nondet_size(void)
{
	return (size_t) qp_cbmc_shape((size_t) -1);
}

void nondet_bytes(uint8_t *buf, size_t n)
{
	size_t i;
	if (n != 0 && n <= 8 && quickproof_rnd() % 4 != 0) {
		uint64_t v;
		switch (quickproof_rnd() % 6) {
		case 0:
		case 1:
		case 2:
			v = quickproof_rnd() % 17;
			break;
		case 3:
			v = quickproof_rnd() % 257;
			break;
		case 4:
			v = quickproof_rnd() % 4097;
			break;
		default:
			v = ~(uint64_t) 0 - quickproof_rnd() % 17;
			break;
		}
		for (i = 0; i < n; i = i + 1) {      /* little-endian: the low bytes first */
			buf[i] = (uint8_t) (v & 255);
			v = v >> 8;
		}
		return;
	}
	for (i = 0; i < n; i = i + 1)
		buf[i] = (uint8_t) quickproof_rnd();
}
